pre-push:
#!/bin/sh
# stayawake-scan-on-clone (pre-push) — installed by `saw hook install` (#1195). Must never fail git.
_local="$(dirname "$0")/pre-push.local"
_feed() { [ -z "$_refs" ] || printf '%s\n' "$_refs"; }
_chain() {
if [ -x "$_local" ]; then "$_local" "$@"; return $?; fi
git config --local --get lfs.repositoryformatversion >/dev/null 2>&1 || { cat >/dev/null; return 0; }
command -v git-lfs >/dev/null 2>&1 || { echo "This repository uses Git LFS, but git-lfs was not found on your path." >&2; return 2; }
git lfs pre-push "$@"
}
_refs="$(cat)"
_feed | /usr/local/bin/saw hook run --config '/home/me/my config.yml' pre-push "$@" || true
_feed | _chain "$@"
exit $?
